        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while count != 0:
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                j += 1
            separated_groups.append(paren_string[i:j])  # Append each extracted group to the list
